+.products { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 1rem; padding: 0; margin: 0; list-style: none; }
+.product { display: grid; gap: 1.15rem; min-height: 180px; padding: 1.25rem; background: #fff; border: 1px solid #dce4dc; border-radius: 1rem; transition: transform .18s ease, box-shadow .18s ease; }
+.product:hover { transform: translateY(-3px); box-shadow: 0 10px 25px rgba(23, 51, 35, .1); }
+.product__category { margin: 0; color: #18794e; font-size: .78rem; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
+.product__name { margin: .3rem 0 0; font-size: 1.18rem; letter-spacing: -.02em; }
+.product__price { align-self: end; margin: 0; font-size: 1.35rem; font-weight: 800; }
+.empty { padding: clamp(2rem, 8vw, 4rem) 1.5rem; text-align: center; background: #fff; border: 1px dashed #aab9ae; border-radius: 1rem; }
+.empty h2 { margin: 0; font-size: 1.35rem; }
+.empty p { margin: .5rem 0 0; color: #56635b; }
+@media (max-width: 680px) { .catalog { width: min(100% - 1.25rem, 1120px); padding-top: 2rem; } .filters, .products { grid-template-columns: 1fr; } }
+@media (prefers-reduced-motion: reduce) { .product { transition: none; } }
